import ast
import inspect
import os
import textwrap
import lexinform.services.card_edits as edits
import lexinform.services.publications as publications


def pytest_sessionstart(session):
    fault = os.environ.get('CARD_TEST_FAULT')
    if not fault:
        return
    module = edits if fault.startswith('card_') else publications
    name = 'edit_card' if module is edits else 'send_publications'
    original = getattr(module, name)
    tree = ast.parse(textwrap.dedent(inspect.getsource(original)))
    function = tree.body[0]
    if fault == 'card_projection_before_send':
        index = next(i for i,n in enumerate(function.body) if isinstance(n,ast.Assign) and any(isinstance(t,ast.Name) and t.id=='sent' for t in n.targets))
        function.body[index:index] = ast.parse('repo.set_card_digest(owner.id, desired)').body
    elif fault == 'card_duplicate_edit_target':
        nodes = [n for n in ast.walk(function) if isinstance(n,ast.keyword) and n.arg=='edit_message_id']
        assert len(nodes)==1
        target = next(n for n in ast.walk(nodes[0]) if isinstance(n,ast.Subscript) and isinstance(n.value,ast.Name) and n.value.id=='targets')
        target.slice=ast.Constant(value=0)
    elif fault == 'delivery_uncertain_as_failed':
        count=0
        for n in ast.walk(function):
            if isinstance(n,ast.Attribute) and isinstance(n.value,ast.Name) and n.value.id=='PublicationStatus' and n.attr=='UNKNOWN':
                n.attr='FAILED';count+=1
        assert count==1
    elif fault == 'delivery_pending_checkpoint_after_send':
        before=next(n for n in function.body if isinstance(n,ast.If) and ast.unparse(n.test)=='checkpoint is not None')
        function.body.remove(before)
        attempt=next(n for n in function.body if isinstance(n,ast.Try))
        attempt.body.insert(1,before)
    elif fault == 'delivery_receipt_checkpoint_removed':
        after=function.body[-2]
        assert isinstance(after,ast.If) and ast.unparse(after.test)=='checkpoint is not None'
        function.body.remove(after)
    else:
        raise ValueError(fault)
    namespace=dict(vars(module))
    exec(compile(ast.fix_missing_locations(tree),'<fault:'+fault+'>','exec'),namespace)
    setattr(module,name,namespace[name])
